#!/usr/bin/env bash
# PreToolUse hook: frontend components are written with the shadcn and vercel-react-best-practices
# SKILL.md files read (see "Skills" in Sandbox/fotoAlbum/frontend/CLAUDE.md).
# Fails closed: if the transcript cannot prove both files were read, the edit is blocked (exit 2).
# components/ui/ is generated by shadcn and exempt. A guard against slips, not against edits made through Bash.
set -u

skills=("shadcn/SKILL.md" "vercel-react-best-practices/SKILL.md")

input=$(cat)
path=$(jq -r '.tool_input.file_path // empty' <<<"$input")

is_frontend_component() {
  case $1 in
    */frontend/src/components/ui/*) return 1 ;;
    */frontend/src/components/*.tsx) return 0 ;;
  esac
  return 1
}

skill_was_read() {
  local transcript=$1 skill=$2
  [[ -r $transcript ]] || return 1
  jq -e --arg s "/skills/$skill" '
    (.message.content // empty) as $c
    | ($c | type) == "array"
      and any($c[]; .type == "tool_use" and .name == "Read" and ((.input.file_path // "") | endswith($s)))
  ' "$transcript" 2>/dev/null | grep -q true
}

is_frontend_component "$path" || exit 0

transcript=$(jq -r '.transcript_path // empty' <<<"$input")
missing=()
for skill in "${skills[@]}"; do
  skill_was_read "$transcript" "$skill" || missing+=("$skill")
done
((${#missing[@]} == 0)) && exit 0

echo "frontend-components-need-skills: read frontend/.claude/skills/{${missing[*]}} before editing $path (Read tool, then retry)." >&2
exit 2
